import numpy as np
from scipy.spatial.transform import Rotation as Rot

def trans(x=0,y=0,z=0):
 T=np.eye(4);T[:3,3]=[x,y,z];return T

def rx(a):
 T=np.eye(4);T[:3,:3]=Rot.from_euler('x',a).as_matrix();return T

def rz(a):
 T=np.eye(4);T[:3,:3]=Rot.from_euler('z',a).as_matrix();return T

def fk(q):
 T=np.eye(4)
 ops=[trans(z=.333),rx(-np.pi/2),trans(y=-.316)@rx(np.pi/2),trans(x=.0825)@rx(np.pi/2),trans(x=-.0825,y=.384)@rx(-np.pi/2),rx(np.pi/2),trans(x=.088)@rx(np.pi/2)]
 for a,o in zip(q,ops):T=T@o@rz(a)
 return T@trans(z=.107)
q=np.array([0,-1.04758,0,-2.63996,0,1.53564,-2.32]);T=fk(q)
print(T)
for deg in [0,90,-90,180]:
 R=Rot.from_euler('z',deg,degrees=True).as_matrix();print(deg,R@T[:3,3])
